def check_provenance_completeness(project: str) -> ToolResult:
    """Check paper provenance completeness.

    Scans paper .tex files for unmapped numbers and figures, verifies
    exp_id/decision_id existence in registry/decisions.yaml, and computes
    Tier 1/2/3/X breakdown.

    Returns:
        ToolResult with completeness report.
    """
    if not project:
        return ToolResult(success=False, error="project is required")

    prov_path = _get_provenance_path(project)
    prov = _read_provenance(prov_path)

    paper_dir = _get_paper_dir(project)
    has_provenance = bool(prov.get("claims") or prov.get("tables") or prov.get("figures"))
    has_paper = paper_dir.exists() and any(paper_dir.glob("*.tex"))

    if not has_provenance and not has_paper:
        return ToolResult(
            success=True,
            data={"status": "no_provenance", "message": "No provenance data or paper files found. Use write_paper_section to start."},
        )

    # Load registry for Tier 1/X checks
    registry: dict = {}
    try:
        from core.tools.registry import get_registry_path
        import yaml as _yaml
        reg_path = get_registry_path(project=project)
        if reg_path.exists():
            with open(reg_path, encoding="utf-8") as f:
                registry = _yaml.safe_load(f) or {}
    except Exception:
        logger.debug("[provenance] could not load registry for completeness check", exc_info=True)

    # Load decisions for reference validation
    decisions_ids: set[str] = set()
    try:
        from core.tools.roadmap import _get_decisions_path, _read_decisions
        dec_data = _read_decisions(_get_decisions_path(project))
        decisions_ids = {d.get("id", "") for d in dec_data.get("decisions", [])}
    except Exception:
        logger.debug("[provenance] could not load decisions for completeness check", exc_info=True)

    issues: list[str] = []
    experiments = registry.get("experiments", {})

    # Verify exp_id references exist in registry
    for c in prov.get("claims", []):
        if c.get("deprecated"):
            continue
        for ev in c.get("evidence", []):
            eid = ev.get("exp_id")
            if eid and eid not in experiments:
                issues.append(f"Claim {c.get('id')}: references non-existent experiment {eid}")
        for did in c.get("decisions", []):
            if did and decisions_ids and did not in decisions_ids:
                issues.append(f"Claim {c.get('id')}: references non-existent decision {did}")

    # Verify figure source exp_ids
    for f in prov.get("figures", []):
        if f.get("deprecated"):
            continue
        for exp_ref in f.get("source", {}).get("experiments", []):
            eid = exp_ref.get("exp_id")
            if eid and eid not in experiments:
                issues.append(f"Figure {f.get('id')}: references non-existent experiment {eid}")

    # Scan .tex files for unmapped numbers and figures
    paper_dir = _get_paper_dir(project)
    unmapped_numbers: list[str] = []
    unmapped_figures: list[str] = []
    if paper_dir.exists():
        # Collect all mapped values from provenance
        mapped_values: set[str] = set()
        for t in prov.get("tables", []):
            if t.get("deprecated"):
                continue
            for cell in t.get("cells", []):
                v = cell.get("value")
                if v is not None:
                    mapped_values.add(str(v))
        for c in prov.get("claims", []):
            if c.get("deprecated"):
                continue
            for ev in c.get("evidence", []):
                v = ev.get("value")
                if v is not None:
                    mapped_values.add(str(v))

        # Collect mapped figure numbers
        mapped_fig_nums: set[int] = set()
        for f in prov.get("figures", []):
            if not f.get("deprecated"):
                mapped_fig_nums.add(f.get("location", {}).get("figure_number", 0))

        for tex_file in sorted(paper_dir.glob("*.tex")):
            content = tex_file.read_text(encoding="utf-8")
            section_name = tex_file.stem
            # Find result-like numbers (e.g. 85.3, 85.3%)
            for m in re.finditer(r'(\d+\.\d+)%?', content):
                if m.group(1) not in mapped_values:
                    unmapped_numbers.append(f"{section_name}: {m.group(0)}")
            # Find \begin{figure} without provenance mapping
            for fm in re.finditer(r'\\begin\{figure\}', content):
                # Try to find figure number from \label or caption
                chunk = content[fm.start():fm.start() + 500]
                fig_num_match = re.search(r'Figure\s+(\d+)', chunk)
                if fig_num_match:
                    fn = int(fig_num_match.group(1))
                    if fn not in mapped_fig_nums:
                        unmapped_figures.append(f"{section_name}: Figure {fn}")

    if unmapped_numbers:
        issues.append(f"{len(unmapped_numbers)} unmapped number(s) in .tex files")
    if unmapped_figures:
        issues.append(f"{len(unmapped_figures)} unmapped figure(s) in .tex files")

    completeness = _compute_completeness(prov, registry=registry)
    completeness["issues"] = issues
    completeness["unmapped_numbers"] = unmapped_numbers[:20]  # cap output
    completeness["unmapped_figures"] = unmapped_figures[:10]
    prov["_completeness"] = {k: v for k, v in completeness.items() if k not in ("unmapped_numbers", "unmapped_figures", "issues")}
    _write_provenance_atomic(prov_path, prov)

    return ToolResult(success=True, data=completeness)

